app.use((req,res,next)=>{res.setHeader('X-Content-Type-Options','nosniff');res.setHeader('X-Frame-Options','DENY');res.setHeader('Referrer-Policy','strict-origin-when-cross-origin');res.setHeader('Permissions-Policy','camera=(),microphone=(),geolocation=()');res.setHeader('X-Robots-Tag','noindex, nofollow, noarchive');res.setHeader('Cross-Origin-Opener-Policy','same-origin');res.setHeader('Cross-Origin-Resource-Policy','same-origin');if(req.secure)res.setHeader('Strict-Transport-Security','max-age=31536000; includeSubDomains');if(req.path.startsWith('/api/')||req.path==='/'||req.path==='/recovery'||req.path==='/recovery.js'||req.path==='/app.js'||req.path.endsWith('.html'))res.setHeader('Cache-Control','no-store, max-age=0');res.setHeader('Content-Security-Policy',"default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; frame-ancestors 'none'; base-uri 'self'; form-action 'self'");if(req.path.startsWith('/api/')&&['POST','PUT','PATCH','DELETE'].includes(req.method)){const origin=req.get('origin');const host=req.get('host');const publicAi=req.path==='/api/public/ai/ask';const allowedPublicOrigins=String(process.env.PUBLIC_WEB_ORIGINS||'').split(',').map(x=>x.trim()).filter(Boolean);if(origin){try{const parsed=new URL(origin);if(publicAi){if(!allowedPublicOrigins.includes(origin))return res.status(403).json({error:'Public AI origin is not allowed'});res.setHeader('Access-Control-Allow-Origin',origin);res.setHeader('Vary','Origin');res.setHeader('Access-Control-Allow-Methods','POST, OPTIONS');res.setHeader('Access-Control-Allow-Headers','Content-Type');}else if(parsed.host!==host)return res.status(403).json({error:'Cross-site request blocked'});}catch{return res.status(403).json({error:'Invalid request origin'})}}if(publicAi&&req.method==='OPTIONS')return res.status(204).end();const cookies=parseCookies(req);const bootstrap=['/api/setup','/api/login','/api/invitations/accept','/api/recovery/reset','/api/public/ai/ask'];if(cookies.amaal_session&&!bootstrap.includes(req.path)){const supplied=req.get('x-csrf-token');const expected=String(cookies.amaal_csrf||'');const provided=String(supplied||'');if(!provided||!expected||provided.length!==expected.length||!crypto.timingSafeEqual(Buffer.from(provided),Buffer.from(expected)))return res.status(403).json({error:'CSRF validation failed'});}}next()});
