function parseCookies(req){const out={};for(const part of String(req.headers.cookie||'').split(';')){const i=part.indexOf('=');if(i>0)out[part.slice(0,i).trim()]=decodeURIComponent(part.slice(i+1).trim())}return out}
function setAuthCookie(res,token,maxAge=43200,deviceId=''){const csrf=crypto.randomBytes(24).toString('base64url');const cookies=[`amaal_session=${encodeURIComponent(token)}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=${Math.max(300,Number(maxAge)||43200)}`,`amaal_csrf=${csrf}; Path=/; Secure; SameSite=Lax; Max-Age=${Math.max(300,Number(maxAge)||43200)}`];if(deviceId)cookies.push(`amaal_device=${encodeURIComponent(deviceId)}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=15552000`);res.setHeader('Set-Cookie',cookies);return csrf}
function clearAuthCookie(res){res.setHeader('Set-Cookie',['amaal_session=; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=0','amaal_csrf=; Path=/; Secure; SameSite=Lax; Max-Age=0','amaal_device=; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=0'])}

