// One-time, explicitly enabled administrator recovery. Keep ADMIN_RECOVERY_TOKEN out of source control.
function safeTokenEqual(a,b){const aa=Buffer.from(String(a||''));const bb=Buffer.from(String(b||''));return aa.length===bb.length&&aa.length>0&&crypto.timingSafeEqual(aa,bb)}
app.get('/recovery',(_req,res)=>{
  const enabled=Boolean(process.env.ADMIN_RECOVERY_TOKEN);
  const state=enabled
    ? '<div id=state class="status ok">Recovery is enabled. Enter the recovery token and type AMAAL-RESET to continue.</div>'
    : '<div id=state class="status">Recovery is currently disabled. Add ADMIN_RECOVERY_TOKEN in Render Environment and redeploy.</div>';
  const formArea=enabled
    ? '<div id=formarea><label>Recovery token<input name=token type=password required autocomplete=off></label><label>Confirmation<input name=confirm placeholder="AMAAL-RESET" required autocomplete=off></label><button type=submit>Reset administrator access</button></div>'
    : '<div id=formarea style="display:none"></div>';
  res.type('html').send(`<!doctype html><html><head><meta name=viewport content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Amaal Telecoms · Administrator Recovery</title><style>*{box-sizing:border-box}body{font-family:system-ui,-apple-system,sans-serif;background:#0b1220;color:#0f172a;margin:0;padding:20px;min-height:100vh;display:grid;place-items:center}.box{width:min(500px,100%);background:#fff;border-radius:24px;padding:28px;box-shadow:0 30px 80px #0008}.brand{font-size:13px;font-weight:900;letter-spacing:.12em;color:#475569;text-transform:uppercase}.warn{background:#fff7ed;color:#9a3412;padding:14px;border-radius:14px;margin:16px 0;line-height:1.5}label{display:block;font-weight:700;margin-top:14px}input,button{font:inherit;width:100%;padding:13px 14px;border-radius:12px;margin-top:7px}input{border:1px solid #cbd5e1}button{border:0;background:#111827;color:#fff;font-weight:800;cursor:pointer}button:disabled{opacity:.6;cursor:wait}.status{padding:12px;border-radius:12px;margin-top:12px;background:#f1f5f9;color:#334155}.bad{background:#fef2f2;color:#991b1b}.ok{background:#ecfdf5;color:#166534}.small{font-size:13px;color:#64748b;line-height:1.5}code{background:#f1f5f9;padding:2px 5px;border-radius:5px}</style></head><body><form class=box id=f><div class=brand>Amaal Telecoms · Security</div><h1>Administrator recovery</h1><p class=small>Use this only when normal administrator access is unavailable. Business records are preserved.</p><div class=warn><b>Important:</b> recovery revokes administrator authentication, trusted devices, MFA credentials, notifications, role links and audit/security/login history, and suspends existing administrator accounts. It does not delete products, sales, inventory, customers, orders, finance or other business records.</div>${state}${formArea}<p class=small>If recovery is not enabled, set <code>ADMIN_RECOVERY_TOKEN</code> in Render Environment and redeploy. Never put that secret in GitHub.</p><div id=msg></div></form><script src="/recovery.js" defer></script></body></html>`)
})
app.get('/api/recovery/status',(_req,res)=>res.json({enabled:Boolean(process.env.ADMIN_RECOVERY_TOKEN),serverTime:new Date().toISOString()}));
app.post('/api/recovery/reset',async(req,res)=>{
  const configured=String(process.env.ADMIN_RECOVERY_TOKEN||'');
  if(!configured)return res.status(404).json({error:'Recovery is disabled. Set ADMIN_RECOVERY_TOKEN in the deployment environment and redeploy.'});
  const token=String(req.body?.token||'');
  if(!safeTokenEqual(token,configured))return res.status(403).json({error:'Invalid recovery token'});
  if(String(req.body?.confirm||'')!=='AMAAL-RESET')return res.status(400).json({error:'Type AMAAL-RESET to confirm'});
  const tokenHash=crypto.createHash('sha256').update(configured).digest('hex');
  const client=await pool.connect();
  try{
    await client.query('BEGIN');
    const used=(await client.query("SELECT value_json FROM settings WHERE key='adminRecoveryTokenHash'")).rows[0];
    const flag=safeJson((await client.query("SELECT value_json FROM settings WHERE key='administratorSetupRequired'")).rows[0]?.value_json);
    if(safeJson(used?.value_json)===tokenHash && Boolean(flag)){
      await client.query("INSERT INTO settings(key,value_json) VALUES('administratorSetupRequired','true') ON CONFLICT(key) DO UPDATE SET value_json='true'::jsonb,updated_at=now(),updated_by=NULL");
      await client.query('COMMIT');
      clearAuthCookie(res);
      return res.json({ok:true,alreadyReset:true,accountsSuspended:0,auditEvents:0,message:'Administrator recovery is already complete. First-time administrator setup is enabled.'});
    }
    if(safeJson(used?.value_json)===tokenHash && !Boolean(flag))return res.status(409).json({error:'This recovery token has already been used. Rotate ADMIN_RECOVERY_TOKEN before another recovery.'});

    // Recovery never deletes users. Historical user rows may be referenced by
    // business records, so deletion is both unsafe and unnecessary. We revoke
    // all authentication state and suspend every administrator account. The
    // setup endpoint can then safely reclaim the same email or create a new one.
    const securityTables=['audit_logs','login_events','security_events','sessions','trusted_devices','mfa_credentials','password_history','user_roles','user_branches','notifications'];
    for(const table of securityTables)await client.query(`DELETE FROM ${table}`);
    const suspended=(await client.query("UPDATE users SET status='Suspended',failed_attempts=0,locked_until=NULL,updated_at=now(),updated_by=NULL WHERE status='Active' RETURNING id")).rowCount;
    await client.query("INSERT INTO settings(key,value_json) VALUES('administratorSetupRequired','true') ON CONFLICT(key) DO UPDATE SET value_json='true'::jsonb,updated_at=now(),updated_by=NULL");
    await client.query("INSERT INTO settings(key,value_json) VALUES('adminRecoveryTokenHash',$1) ON CONFLICT(key) DO UPDATE SET value_json=EXCLUDED.value_json,updated_at=now(),updated_by=NULL",[JSON.stringify(tokenHash)]);
    await client.query('COMMIT');
    clearAuthCookie(res);
    res.setHeader('Cache-Control','no-store, max-age=0');
    res.json({ok:true,accountsSuspended:suspended,auditEvents:0,accountsDeleted:false,message:'Administrator access has been reset. Business records were preserved. First-time administrator setup is now ready.'});
  }catch(e){try{await client.query('ROLLBACK')}catch{}console.error('Recovery reset failed',e);res.status(500).json({error:'Recovery failed. No changes were committed.'});}
  finally{client.release()}
});

app.post('/api/login',async(req,res)=>{const ip=req.ip;const now=Date.now();const a=loginAttempts.get(ip)||{count:0,until:0};if(a.until>now)return res.status(429).json({error:'Too many sign-in attempts. Try again later.'});const {email,password,code}=req.body||{};const normalized=String(email||'').toLowerCase().trim();const u=(await q('SELECT * FROM users WHERE email=$1',[normalized]))[0];const rid=requestId();if(!u){a.count++;if(a.count>=8)a.until=now+15*60000;loginAttempts.set(ip,a);await pool.query('INSERT INTO login_events(email,success,reason,ip,user_agent,request_id) VALUES($1,false,$2,$3,$4,$5)',[normalized,'Invalid credentials',req.ip,req.get('user-agent'),rid]);return res.status(401).json({error:'Invalid credentials'})}if(u.status!=='Active')return res.status(403).json({error:'Account inactive'});if(u.locked_until&&new Date(u.locked_until)>new Date())return res.status(423).json({error:'Account temporarily locked'});const ok=await bcrypt.compare(password||'',u.password_hash);if(!ok){a.count++;if(a.count>=8)a.until=now+15*60000;loginAttempts.set(ip,a);const attempts=u.failed_attempts+1;const policy=await q("SELECT key,value_json FROM settings WHERE key = ANY($1)",[['maxLoginAttempts','lockoutMinutes']]);const po=Object.fromEntries(policy.map(x=>[x.key,safeJson(x.value_json)]));const limit=Number(po.maxLoginAttempts||5),minutes=Number(po.lockoutMinutes||15);const locked=attempts>=limit?new Date(Date.now()+minutes*60000):null;await pool.query('UPDATE users SET failed_attempts=$1,locked_until=$2,updated_at=now() WHERE id=$3',[attempts,locked,u.id]);await pool.query('INSERT INTO login_events(user_id,email,success,reason,ip,user_agent,request_id) VALUES($1,$2,false,$3,$4,$5,$6)',[u.id,normalized,locked?'Account locked after failed attempts':'Invalid credentials',req.ip,req.get('user-agent'),rid]);return res.status(401).json({error:locked?'Too many attempts. Account temporarily locked.':'Invalid credentials'})}const mfaRequired=Boolean(safeJson((await q("SELECT value_json FROM settings WHERE key='mfaRequired'"))[0]?.value_json||false));const deviceId=getOrCreateDeviceId(req);const dHash=deviceHash(deviceId);const trusted=(await q('SELECT id FROM trusted_devices WHERE user_id=$1 AND device_hash=$2 AND revoked_at IS NULL',[u.id,dHash]))[0];const firstLogin=!u.last_login_at&&!trusted;const newDevice=!trusted&&!firstLogin;const mfaEnforced=MFA_LOGIN_ENABLED&&(mfaRequired||newDevice);if(mfaEnforced&&!u.mfa_enabled){if(newDevice)return res.status(403).json({error:'MFA is required before signing in from a new device. Sign in from a trusted device and enable MFA first.'});return res.status(403).json({error:'MFA is required for this account. Enable it before signing in.'})}if(mfaEnforced&&u.mfa_enabled){const row=(await q('SELECT secret_encrypted FROM mfa_credentials WHERE user_id=$1',[u.id]))[0];if(!row||!verifyTotp(decryptSecret(row.secret_encrypted),code)){a.count++;if(a.count>=8)a.until=now+15*60000;loginAttempts.set(ip,a);await pool.query('INSERT INTO login_events(user_id,email,success,reason,ip,user_agent,request_id) VALUES($1,$2,false,$3,$4,$5,$6)',[u.id,normalized,'MFA verification failed',req.ip,req.get('user-agent'),rid]);return res.status(401).json({error:'Authenticator code required or invalid'})}await pool.query('INSERT INTO trusted_devices(user_id,device_hash,label,last_ip,user_agent) VALUES($1,$2,$3,$4,$5) ON CONFLICT(user_id,device_hash) DO UPDATE SET last_seen_at=now(),last_ip=EXCLUDED.last_ip,user_agent=EXCLUDED.user_agent,revoked_at=NULL',[u.id,dHash,'Trusted device',req.ip,req.get('user-agent')||''])}else if(!trusted){await pool.query('INSERT INTO trusted_devices(user_id,device_hash,label,last_ip,user_agent) VALUES($1,$2,$3,$4,$5) ON CONFLICT(user_id,device_hash) DO UPDATE SET last_seen_at=now(),last_ip=EXCLUDED.last_ip,user_agent=EXCLUDED.user_agent,revoked_at=NULL',[u.id,dHash,'Trusted device',req.ip,req.get('user-agent')||''])}await pool.query('UPDATE users SET failed_attempts=0,locked_until=null,last_login_at=now() WHERE id=$1',[u.id]);const sessionMinutes=Number((await q("SELECT value_json FROM settings WHERE key='sessionMinutes'"))[0]?.value_json||720);const sid=crypto.randomUUID();await pool.query('INSERT INTO sessions(id,user_id,token_hash,device_hash,user_agent_hash,expires_at,ip,user_agent) VALUES($1,$2,$3,$4,$5,now()+($6 || \' minutes\')::interval,$7,$8)',[sid,u.id,crypto.createHash('sha256').update(sid+JWT_SECRET).digest('hex'),dHash,userAgentHash(req.get('user-agent')),sessionMinutes,req.ip,req.get('user-agent')]);await pool.query('INSERT INTO login_events(user_id,email,success,reason,ip,user_agent,request_id) VALUES($1,$2,true,$3,$4,$5,$6)',[u.id,normalized,newDevice?'Login successful after MFA new-device verification':'Login successful',req.ip,req.get('user-agent'),rid]);await audit(u,'LOGIN','Authentication',u.id,newDevice?'Administrator signed in with new trusted device':'Administrator signed in',null,null,{id:rid,ip:req.ip,ua:req.get('user-agent')});loginAttempts.delete(ip);setAuthCookie(res,sign(u,sid),sessionMinutes*60,deviceId);res.json({user:{id:u.id,name:u.name,email:u.email,status:u.status,mfaEnabled:u.mfa_enabled,mfaSetupRecommended:firstLogin&&!u.mfa_enabled}})});
